$('exportBtn').onclick=()=>{if(previewPending||!cutPaths.length)return;const [w,h]=PAPERS[state.paper],margin=Math.max(0,state.clearance)+.75;if(state.tools.some(t=>{const b=bounds(t.points);return b.minX<margin||b.minY<margin||b.maxX>w-margin||b.maxY>h-margin;})||state.fingers.some(f=>f.x-f.r<.75||f.y-f.r<.75||f.x+f.r>w-.75||f.y+f.r>h-.75)){toast('Move cutouts inward so the full clearance fits inside the sheet.');return;}if(cutPaths.some(p=>p.some(([x,y])=>x<.5||y<.5||x>w-.5||y>h-.5))){toast('A cut path reaches the sheet edge. Move the tool inward before export.');return;}const format=$('exportFormat').value,name=(projectName||'toolnest').replace(/[^a-z0-9_-]/gi,'-');download(format==='svg'?exportSVG(cutPaths,state.paper):exportDXF(cutPaths,state.paper),`${name}.${format}`,format==='svg'?'image/svg+xml':'application/dxf');toast(`${format.toUpperCase()} exported in mm. Verify scale and cutting depth in CAM.`);};
function projectData(includeFoam=true){return {format:'toolnest-project',version:2,name:projectName,paper:state.paper,tools:state.tools,fingers:state.fingers,...Object.fromEntries(Object.keys(DEFAULT_SETTINGS).map(k=>[k,state[k]])),...(includeFoam?{foamDesigner:foamStudio.getData()}:{})};}
function validateProject(d){const finite=n=>typeof n==='number'&&Number.isFinite(n);if(d.format!=='toolnest-project'||![1,2].includes(d.version)||!PAPERS[d.paper]||!Array.isArray(d.tools)||d.tools.length>50||!Array.isArray(d.fingers)||d.fingers.length>100||!finite(d.clearance)||d.clearance< -2||d.clearance>5||!Number.isInteger(d.smoothing)||d.smoothing<0||d.smoothing>5)throw Error();let count=0;for(const t of d.tools){if(typeof t.name!=='string'||t.name.length>60||!Array.isArray(t.points)||t.points.length<3)throw Error();count+=t.points.length;for(const p of t.points)if(!Array.isArray(p)||p.length!==2||p.some((v,i)=>!finite(v)||v<1||v>PAPERS[d.paper][i]-1))throw Error();}if(count>20000)throw Error();for(const f of d.fingers)if(![f.x,f.y,f.r].every(finite)||f.r<3||f.r>25||f.x<0||f.y<0||f.x>PAPERS[d.paper][0]||f.y>PAPERS[d.paper][1]||!Number.isInteger(f.tool)||f.tool<0||f.tool>=d.tools.length)throw Error();if(d.foamDesigner)validateFoam(d.foamDesigner);return d;}
function loadProject(d,withFoam=true){if(outlineSession)endOutlineSession(false);validateProject(d);const finite=n=>typeof n==='number'&&Number.isFinite(n);clearProject(d.paper);Object.assign(state,{tools:d.tools,fingers:d.fingers,clearance:d.clearance,smoothing:d.smoothing,threshold:finite(d.threshold)?Math.max(50,Math.min(235,d.threshold)):160,brightnessThreshold:finite(d.brightnessThreshold)?Math.max(0,Math.min(255,d.brightnessThreshold)):d.traceMethod==='dark'&&finite(d.threshold)?Math.max(0,Math.min(255,d.threshold)):160,traceMethod:d.traceMethod==='dark'?'dark':'edges',smoothingMode:['fair','round','detail','relax'].includes(d.smoothingMode)?d.smoothingMode:'round',curveRadius:finite(d.curveRadius)?Math.max(.1,Math.min(3,d.curveRadius)):.75,maxDeviation:finite(d.maxDeviation)?Math.max(.05,Math.min(1.5,d.maxDeviation)):.35,simplification:finite(d.simplification)?Math.max(0,Math.min(1.5,d.simplification)):.18,weakRatio:finite(d.weakRatio)?Math.max(.1,Math.min(.8,d.weakRatio)):.4,gapMm:finite(d.gapMm)?Math.max(0,Math.min(2,d.gapMm)):1,minToolArea:finite(d.minToolArea)?Math.max(1,Math.min(200,d.minToolArea)):20,selected:0,demo:false});projectName=typeof d.name==='string'?d.name.slice(0,80):'Imported project';if(withFoam){if(d.foamDesigner)foamStudio.load(d.foamDesigner);else foamStudio.clear();}activeNode=-1;syncInputs();setMobilePanel('workspace');render();if(withFoam&&d.foamDesigner?.tools.length)foamStudio.show();}
$('saveBtn').onclick=()=>{if(previewError)return toast('Resolve the preview error before saving.');if(previewPending)return toast('Wait for the outline preview to finish.');const data=projectData();download(JSON.stringify(data,null,2),`${(data.foamDesigner?.name||data.name||'toolnest').replace(/[^a-z0-9_-]/gi,'-')}.toolnest.json`,'application/json');toast('Project saved with tools, foam layout and depths. The foam-photo checkbox controls photo inclusion.');};
$('openBtn').onclick=()=>$('projectInput').click();$('projectInput').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10e6)throw Error();const d=JSON.parse(await file.text());validateProject(d);loadProject(d);toast('Project opened. Tool-source photos remain excluded.');}catch{toast('This is not a valid Toolnest project file.');}};
function showLab(){showModal('Put perspective to the test.','DISTORTION TEST LAB',`<p>Generate photographed sheets with known geometry, detect their codes, and correct them with the same engine used for uploads. Accuracy is checked at an independent grid of points inside the page.</p><div id="labMetrics"></div><table class="lab-table"><thead><tr><th>GENERATED PHOTO</th><th>RMS ERROR</th><th>MAX ERROR</th><th>RESULT</th></tr></thead><tbody id="labRows"></tbody></table><div class="progress-line"><span id="labProgress" style="width:0"></span></div><p id="labStatus">Pass criteria: grid RMS &lt; 0.5 mm, maximum &lt; 1.0 mm. A missing square must be rejected.</p><div class="modal-actions"><button class="primary" id="runTests">Run distortion tests ↻</button><button class="secondary" id="downloadReport">Download report ↓</button></div><p>These are synthetic perspective tests. They do not validate a physical print, your camera’s lens, tool height, or the final cut. Run a test cut and measure your fit.</p>`);drawLab();$('runTests').onclick=runLab;$('downloadReport').onclick=()=>{if(!testResults.length)return toast('Run the tests first.');download(JSON.stringify({engine:'Toolnest planar calibration v1',date:new Date().toISOString(),criteria:{rmsMm:.5,maxMm:1},results:testResults},null,2),'toolnest-distortion-report.json','application/json');};}
function drawLab(){if(!$('labRows'))return;$('labRows').replaceChildren();for(const spec of TEST_CASES){const r=testResults.find(r=>r.name===spec.name),row=document.createElement('tr');for(const text of [spec.name,r?.rms?.toFixed(3)?`${r.rms.toFixed(3)} mm`:'—',r?.max?.toFixed(3)?`${r.max.toFixed(3)} mm`:'—',r?(r.pass?(r.rejected?'Rejected ✓':'Pass ✓'):'Failed'):'Not run']){const td=document.createElement('td');td.textContent=text;row.append(td);}if(r)row.lastChild.className=r.pass?'pass':'fail';$('labRows').append(row);}if(testResults.length){const measured=testResults.filter(r=>r.rms!==undefined),max=Math.max(0,...measured.map(r=>r.max));$('labMetrics').innerHTML=`<div class="metrics"><div class="metric"><strong>${testResults.filter(r=>r.pass).length} / ${TEST_CASES.length}</strong><span>TESTS PASSED</span></div><div class="metric"><strong>${max.toFixed(3)} mm</strong><span>WORST GRID ERROR</span></div><div class="metric"><strong>${measured.reduce((a,r)=>a+r.points,0)}</strong><span>INDEPENDENT CHECK POINTS</span></div></div>`;}}
async function runLab(){$('runTests').disabled=true;testResults=[];for(let i=0;i<TEST_CASES.length;i++){const spec=TEST_CASES[i];$('labStatus').textContent=`Testing ${i+1} of ${TEST_CASES.length}: ${spec.name}…`;await new Promise(r=>setTimeout(r,35));try{const fixture=makeFixture(spec),c=calibrate(fixture),m=evaluateCalibration(c,fixture);testResults.push({name:spec.name,pass:!spec.expectReject&&m.rms<.5&&m.max<1,rms:m.rms,max:m.max,points:m.n,markerRms:c.rms,quad:spec.quad});}catch(e){testResults.push({name:spec.name,pass:!!spec.expectReject,rejected:true,message:e.message,points:0});}if(!$('labRows'))return;drawLab();$('labProgress').style.width=`${(i+1)/TEST_CASES.length*100}%`;}$('runTests').disabled=false;$('labStatus').textContent=`${testResults.filter(r=>r.pass).length} of ${TEST_CASES.length} tests passed. Run again to repeat the full correction pipeline.`;}
$('testBtn').onclick=showLab;$('mobileLabBtn').onclick=showLab;

const ICONS={pan:'M4 8V4a1 1 0 0 1 2 0v3-5a1 1 0 0 1 2 0v5-4a1 1 0 0 1 2 0v4-2a1 1 0 0 1 2 0v5c0 4-2 5-5 5L3 9a1 1 0 0 1 1-1z',upload:'M8 11V2m-3 3 3-3 3 3M3 10v4h10v-4',external:'M4 12 12 4M4 4h8v8',print:'M4 6V2h8v4M4 12H2V6h12v6h-2M4 9h8v5H4z',select:'m3 2 10 6-5 1-2 5z',edit:'M3 3h10v10H3zM1 1h4v4H1zM11 11h4v4h-4z',finger:'M13 10a5 5 0 1 1-10 0c0-2 1-4 5-8 4 4 5 6 5 8z',undo:'M6 3 2 7l4 4M2 7h7a4 4 0 0 1 4 4v2',redo:'m10 3 4 4-4 4M14 7H7a4 4 0 0 0-4 4v2',folder:'M2 4h5l2-2h5v11H2z',pen:'m3 10 7-7 3 3-7 7-4 1zM9 4l3 3',grid:'M2 2h12v12H2zM6 2v12m4-12v12M2 6h12M2 10h12'};
function icon(name){return `<svg class="ui-icon" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[name]}"/></svg>`;}
for(const [id,name] of [['selectMode','select'],['panMode','pan'],['editMode','edit'],['fingerMode','finger'],['undoBtn','undo'],['redoBtn','redo'],['renameBtn','pen'],['gridBtn','grid']])$(id).innerHTML=icon(name);
document.querySelector('.upload-icon').innerHTML=icon('upload');$('printBtn').querySelector('span').innerHTML=icon('print');$('printBtn').querySelector('span:last-child').innerHTML=icon('external');$('exportBtn').querySelector('span').innerHTML=icon('external');$('inspectBtn').textContent='i';

/* Outline editing for a single foam/library tool: Trace's own state is set
   aside, the tool is shown alone on a clean sheet with no clearance or
   smoothing, and the edited points are handed back when the user is done. */
let outlineSession=null;
function editOutline({shape,name},onDone){
 if(busy)return toast('Wait for the current photo to finish processing.');
 if(outlineSession)endOutlineSession(false);
 const [W,H]=PAPERS.a4,rings=shape.map(poly=>poly[0].slice(0,poly[0].length-(poly[0].length>1&&poly[0][0][0]===poly[0].at(-1)[0]&&poly[0][0][1]===poly[0].at(-1)[1]?1:0))),b=bounds(rings.flat()),w=b.maxX-b.minX,h=b.maxY-b.minY,room=[W-8,H-8];
 const turn=w<=room[0]&&h<=room[1]?false:h<=room[0]&&w<=room[1]?true:null;
 if(turn===null)return toast(`This tool is ${w.toFixed(0)} × ${h.toFixed(0)} mm, larger than the outline editor sheet (${room[0]} × ${room[1]} mm).`);
 const sw=turn?h:w,sh=turn?w:h,ox=(W-sw)/2,oy=(H-sh)/2;
 const toSheet=([x,y])=>{x-=b.minX;y-=b.minY;return turn?[ox+h-y,oy+x]:[ox+x,oy+y];},fromSheet=([x,y])=>{x-=ox;y-=oy;return turn?[y+b.minX,h-x+b.minY]:[x+b.minX,y+b.minY];};
 invalidatePreview();
 outlineSession={onDone,fromSheet,saved:{state:JSON.stringify(state),cutPaths,cutOwners,source,corrected,sourceURL,correctedURL,view,mode,zoom,pan:{...pan},history,future,geometryTraceKey,activeNode}};
 Object.assign(state,{paper:'a4',clearance:0,smoothing:0,cal:null,demo:false,selected:0,fingers:[],tools:rings.map((r,i)=>({name:rings.length>1?`${name} · part ${i+1}`:name,points:r.map(toSheet)}))});
 source=corrected=null;sourceURL=correctedURL='';cutPaths=[];cutOwners=[];geometryTraceKey=null;history=[];future=[];view='outline';mode='edit';activeNode=-1;zoom=1;pan={x:0,y:0};
 foamStudio.hide();document.body.classList.add('outline-session');$('outlineSessionName').textContent=name;syncInputs();setMobilePanel('workspace');applyZoom();render();
}
function endOutlineSession(apply){
 const session=outlineSession;if(!session)return;
 const rings=apply?state.tools.map(t=>t.points.map(session.fromSheet)):null;
 outlineSession=null;document.body.classList.remove('outline-session');invalidatePreview();
 const saved=session.saved;Object.assign(state,JSON.parse(saved.state));({cutPaths,cutOwners,source,corrected,sourceURL,correctedURL,view,mode,zoom,history,future,geometryTraceKey,activeNode}=saved);pan=saved.pan;
 syncInputs();applyZoom();render(false);
 foamStudio.show();if(rings)session.onDone(rings);
}
foamStudio=createFoamStudio({editOutline,toast,download,modal:showModal,capture:()=>setMobilePanel('capture'),captureFoam:()=>liveCamera.open({onFrame:image=>foamStudio.captureFoamImage(image)}),saveProject:()=>$('saveBtn').click(),openProject:()=>$('openBtn').click(),setStudio:mode=>{for(const [id,m] of [['traceStudioBtn','trace'],['foamStudioBtn','foam']])$(id).setAttribute('aria-pressed',String(m===mode));}});
$('traceStudioBtn').onclick=()=>foamStudio.hide();$('foamStudioBtn').onclick=()=>{if(outlineSession)endOutlineSession(false);else foamStudio.show();};$('outlineSessionDone').onclick=()=>endOutlineSession(true);$('outlineSessionCancel').onclick=()=>endOutlineSession(false);$('libraryBtn').onclick=()=>foamStudio.openLibrary();
function captureProfile(i){if(previewError||previewPending)return null;const t=state.tools[i];if(!t)return null;return makeCutPaths([t.points],state.fingers.filter(f=>f.tool===i),state.paper,state.clearance,state.smoothing,{mode:state.smoothingMode,simplification:state.simplification,radius:state.curveRadius,maxDeviation:state.maxDeviation});}
$('saveCaptureTool').onclick=()=>{const paths=captureProfile(state.selected);if(paths)foamStudio.addCaptured(paths,state.tools[state.selected].name,true);};$('addCaptureTool').onclick=()=>{const paths=captureProfile(state.selected);if(paths)foamStudio.addCaptured(paths,state.tools[state.selected].name);};$('addAllToFoam').onclick=()=>{state.tools.forEach((t,i)=>{const paths=captureProfile(i);if(paths)foamStudio.addCaptured(paths,t.name);});};
let restored=false;try{const draft=localStorage.getItem('toolnest.trace.v2');if(draft){loadProject(JSON.parse(draft),false);restored=true;}}catch{toast('Could not restore the last photo outlines. Open a project backup.');}
syncInputs();render();if(!restored&&!foamStudio.hasTools())setTimeout(()=>processImage(makeFixture(),true),100);else if(foamStudio.hasTools())foamStudio.show();

const liveCamera=createLiveCamera({settings:()=>({...Object.fromEntries(Object.keys(DEFAULT_SETTINGS).map(k=>[k,state[k]])),paper:state.paper}),useFrame:(image,isActive)=>processImage(image,false,{requireTools:true,isActive})});
$('liveCameraBtn').onclick=()=>liveCamera.open();
for(const button of document.querySelectorAll('[data-outline-preset]'))button.onclick=()=>{remember();const presets={detail:{smoothing:1,curveRadius:.35,maxDeviation:.15},balanced:{smoothing:2,curveRadius:.75,maxDeviation:.35},smooth:{smoothing:4,curveRadius:1.5,maxDeviation:.65}};Object.assign(state,{smoothingMode:'fair'},presets[button.dataset.outlinePreset]);syncInputs();render();};
